BUILDERS = {"small": small, "wide": wide}


def build(name):
    return BUILDERS[name]()

@torch.no_grad()
def evaluate(student, batches):
    student.eval()
    correct, count = 0, 0
    for features, labels in batches:
        predictions = student(features).argmax(dim=-1)
        correct += (predictions == labels).sum().item()
        count += len(labels)
    return correct / count if count else None

@torch.no_grad()
def predict(checkpoint, features):
    student = build("small")
    student.load_state_dict(torch.load(checkpoint, map_location="cpu", weights_only=True))
    student.eval()
    return student(features).argmax(dim=-1)
